from google.cloud import documentai_v1 as documentai

def validate_document_fields(payload, config=None):
    config = config or {}
    # This function assumes `payload` is a google.cloud.documentai_v1.types.Document object.
    required_fields = config.get("required_fields", {})
    validation_report = {
        "overall_status": "VALID",
        "field_results": {}
    }

    extracted_fields = {entity.type_: entity for entity in payload.entities}

    for field_name, min_confidence in required_fields.items():
        if field_name not in extracted_fields:
            validation_report["field_results"][field_name] = {
                "status": "MISSING",
                "message": f"Required field '{field_name}' not found."
            }
            validation_report["overall_status"] = "INVALID"
        else:
            entity = extracted_fields[field_name]
            if entity.confidence >= min_confidence:
                validation_report["field_results"][field_name] = {
                    "status": "VALID",
                    "value": entity.mention_text,
                    "confidence": entity.confidence
                }
            else:
                validation_report["field_results"][field_name] = {
                    "status": "INVALID_CONFIDENCE",
                    "message": f"Confidence {entity.confidence:.2f} is below threshold of {min_confidence:.2f}.",
                    "value": entity.mention_text,
                    "confidence": entity.confidence
                }
                validation_report["overall_status"] = "INVALID"

    result = validation_report
    return result
